package net.battlespades;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import net.battlespades.app.Main;
import net.battlespades.ugc.*;
import net.battlespades.world.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class UgcWorkspaceIntegrationTest {
    @TempDir Path temp;
    private static final byte[] SOURCE={0,(byte)239,(byte)239,0,1,2,3,4};
    private UgcAssets assets()throws IOException{Path root=temp.resolve("retail"),maps=root.resolve("ugc/maps"),prefabs=root.resolve("ugc/kv6");Files.createDirectories(maps);Files.createDirectories(prefabs);for(var t:UgcProject.TERRAINS){Files.write(maps.resolve(t.stem().toUpperCase(Locale.ROOT)+".VXL"),SOURCE);Files.writeString(maps.resolve(t.stem()+".txt"),"skybox_texture = 'User_Grassland.txt'\nground_colors = ((1,2,3,4),(5,6,7,8))\n");}Files.write(prefabs.resolve("UGC_PREFAB_PRIMITIVE_BLOCK.KV6"),new byte[]{1});Files.write(prefabs.resolve("not_a_retail_model.kv6"),new byte[]{1});return UgcAssets.discover(List.of(root));}
    @Test void cliCreatesReopensValidatesAndProtectsTheActualRetailTriplet()throws Exception{var a=assets();var output=new ByteArrayOutputStream();var error=new ByteArrayOutputStream();var out=new PrintStream(output);var err=new PrintStream(error);var dir=temp.resolve("projects");assertEquals(0,Main.run(new String[]{"--ugc-assets",a.root().toString()},out,err));assertEquals(List.of("UGC_PREFAB_PRIMITIVE_BLOCK"),a.compatible(UgcProject.terrain("grassland")));String[] command={"--ugc-create",a.root().toString(),dir.toString(),"My Project","grassland","ctf"};assertEquals(0,Main.run(command,out,err));var p=UgcWorkspace.open(dir,"My Project",null);assertArrayEquals(SOURCE,p.source());assertEquals("My Project",p.project().title());assertEquals("User_Grassland.txt",p.project().skybox());assertEquals(List.of(1,2,3,4),p.project().groundColors().getFirst());assertEquals(0,Main.run(new String[]{"--ugc-check",dir.toString(),"My Project"},out,err));assertEquals(2,Main.run(command,out,err));assertArrayEquals(SOURCE,Files.readAllBytes(p.files().vxl()));assertEquals(2,Main.run(new String[]{"--ugc-check",dir.toString(),"Missing"},out,err));assertTrue(output.toString(java.nio.charset.StandardCharsets.UTF_8).contains("solids=1"));assertTrue(error.toString(java.nio.charset.StandardCharsets.UTF_8).contains("already exists"));}
    @Test void canonicalWorldSavePreviewAndRecreationRetainAuthoredFiles()throws Exception{var a=assets();Path dir=UgcWorkspace.publishDirectory(temp.resolve("client/hosted_ugc"));var project=new UgcProject("Alpha","Description","Author","grassland","ctf");var opened=UgcWorkspace.create(project,dir,"Alpha",a,false);var workspace=new UgcWorkspace(opened.files());try(var world=new MutableWorld(VxlMap.load(opened.source(),"retail"),1,128)){var cell=new MutableWorld.Cell(255,255,238);world.set(cell,true,0xaabbcc,null);project.place(255,255,237,7);var snapshot=UgcWorkspace.capture(world,project);world.set(cell,true,0x010203,null);workspace.save(snapshot);var saved=UgcWorkspace.open(dir,"Alpha",null);var loaded=VxlMap.load(saved.source(),"retail");assertTrue(loaded.solid(255,255,238));assertEquals(0xaabbcc,loaded.color(255,255,238)&0xffffff);assertEquals(project.placements(),saved.project().placements());byte[] png={(byte)137,80,78,71,13,10,26,10,1};assertTrue(workspace.preview(png));assertArrayEquals(png,workspace.preview().orElseThrow());assertFalse(workspace.preview(new byte[]{1,2,3}));assertArrayEquals(png,workspace.preview().orElseThrow());assertFalse(Files.exists(opened.files().sidecar().resolveSibling("Alpha.ugc.tmp")));}Files.delete(opened.files().vxl());Files.delete(opened.files().sidecar());Files.writeString(opened.files().metadata(),"orphan");var recreated=UgcWorkspace.create(project,dir,"Alpha",a,false);assertNotEquals("orphan",Files.readString(recreated.files().metadata()));assertThrows(IllegalArgumentException.class,()->UgcWorkspace.publishDirectory(temp.resolve("client/maps")));}
    @Test void workerPersistsFrozenSnapshotsWithoutAccessingTheLiveWorld()throws Exception{var a=assets();var p=new UgcProject("Worker","","","lunar","tdm");var opened=UgcWorkspace.create(p,temp.resolve("saves"),"Worker",a,false);var store=new UgcWorkspace(opened.files());try(var world=new MutableWorld(VxlMap.load(SOURCE,"retail"),1,128);var worker=java.util.concurrent.Executors.newSingleThreadExecutor()){var snapshot=UgcWorkspace.capture(world,p);p.title("After snapshot");worker.submit(()->{try{store.save(snapshot);}catch(IOException e){throw new java.io.UncheckedIOException(e);}}).get();assertEquals("Worker",UgcWorkspace.open(temp.resolve("saves"),"Worker",null).project().title());assertThrows(java.util.concurrent.ExecutionException.class,()->worker.submit(()->world.solid(255,255,239)).get());}}
}
